INSERT INTO smeshariki_quotes (text, character) VALUES
    ('Какой вообще смысл быть по утрам?', 'Бараш'),
    ('Иногда даже самые привычные вещи внезапно теряют смысл. И непонятно, исчез ли смысл на самом деле или ты просто перестал его замечать.', 'Бараш'),
    ('Зачем заботиться о здоровье, если не понимаешь, ради чего вообще живёшь?', 'Бараш'),
    ('А что, если выяснится, что смысл жизни требует отказаться от всего, что тебе нравится?', 'Кар-Карыч'),
    ('Мы так стремимся найти один правильный смысл для всех, потому что не можем смириться с тем, что каждый видит мир по-своему.', 'Бараш'),
    ('Иногда не нужен ответ на главный вопрос мироздания. Достаточно горячей еды, тёплой кровати и возможности отдохнуть.', 'Бараш'),
    ('Вдохновение способно сделать лёгким даже то, что прежде казалось неподъёмным.', 'Бараш'),
    ('Можно быть окружённым друзьями и всё равно чувствовать одиночество, когда никто не понимает, что тебя тревожит.', 'Кар-Карыч'),
    ('Мы часто слишком заняты попытками докричаться до других и слишком мало стараемся их понять.', 'Кар-Карыч'),
    ('Ощущение полной пустоты вокруг иногда рождается не из отсутствия людей, а из нашей неспособности заметить их.', 'Кар-Карыч'),
    ('Мы стараемся совершать великие поступки ради тех, кому они не нужны, а по-настоящему близкие любят нас и без достижений.', 'Лосяш'),
    ('Даже самые красивые горы могут ничего не значить, пока рядом нет человека, с которым хочется разделить этот момент.', 'Бараш'),
    ('Быть вместе — не значит одинаково воспринимать красоту. Иногда для одного счастье — смотреть на горы, а для другого — есть конфеты.', 'Бараш и Нюша'),
    ('Личные победы не всегда стоят волнений, которые из-за нас испытывают близкие.', 'Кар-Карыч'),
    ('Чужие чувства заслуживают уважения, даже когда кажутся странными. Искренней любви в мире и так недостаточно.', 'Кар-Карыч'),
    ('Друзья — это не дерево. Они не привязаны к одному месту и имеют право уходить.', 'Неизвестно'),
    ('Если человеку трудно расстаться с ненужным зонтиком, разве можно ожидать, что он легко бросит того, с кем прожил столько лет?', 'Неизвестно'),
    ('Даже если тебе постоянно не везёт, встреча с настоящими друзьями способна перевесить все неудачи.', 'Копатыч'),
    ('Изменить другого насильно невозможно. Настоящие перемены начинаются тогда, когда человек сам к ним готов.', 'Крош'),
    ('Иногда чужие ожидания заставляют нас жить жизнью, которую мы никогда не выбирали.', 'Лосяш'),
    ('Помощь, навязанная против воли, легко превращается в лишение свободы.', 'Копатыч'),
    ('Испытания раскрывают не только твой собственный характер, но и характер тех, кто проходит через них вместе с тобой.', 'Ёжик'),
    ('Человек боится будущего или прошлого, но настоящее проходит так быстро, что испугаться его почти невозможно.', 'Рассказчик'),
    ('С возрастом даже поражения становятся частью драгоценного жизненного опыта.', 'Кар-Карыч'),
    ('Хорошо, когда все неприятные воспоминания жизни можно уместить в один чемодан. У кого-то их накопилось бы на целый поезд.', 'Кар-Карыч'),
    ('Мы предпочитаем помнить хорошее и забывать ошибки, потому что иначе жить становится слишком тяжело. Но полностью убежать от самого себя всё равно невозможно.', 'Кар-Карыч'),
    ('Мы часто понимаем ценность привычных возможностей только после того, как их лишаемся.', 'Лосяш'),
    ('При всей уверенности в наших знаниях мы остаёмся существами на маленьком куске скалы, летящем через бесконечный космос.', 'Ёжик'),
    ('Иногда кажется, будто весь наш мир кем-то нарисован и кто-то постоянно наблюдает за происходящим.', 'Ёжик'),
    ('Красивое объяснение мира порой кажется привлекательнее настоящего, потому что реальность не обязана быть интересной.', 'Крош'),
    ('Когда случайность разрушает твои планы, может возникнуть желание больше никогда ничего не планировать.', 'Пин'),
    ('Мы часто отправляем не те слова не тем людям, а самое важное иногда вообще не доходит до адресата.', 'Бараш'),
    ('Нам хочется верить, что для каждого момента жизни существует правильная инструкция, которой достаточно следовать.', 'Совунья'),
    ('Можно лишиться множества привычных удовольствий, но без красоты жизнь оказывается гораздо беднее.', 'Рассказчик'),
    ('В каждом скрывается что-то прекрасное, но иногда этому просто необходимы подходящие условия, чтобы проявиться.', 'Рассказчик');
